static int *prices;
static int *types;

static int type_less(int a, int b) {
    return prices[a] < prices[b];
}

static int global_less(int a, int b) {
    if (prices[a] != prices[b]) return prices[a] < prices[b];
    return types[a] < types[b];
}

static void sift_type(int *heap, int start, int end, int pos) {
    while (1) {
        int left = start + 2 * (pos - start) + 1;
        if (left >= end) break;

        int best = left;
        int right = left + 1;
        if (right < end && type_less(heap[right], heap[left])) best = right;

        if (!type_less(heap[best], heap[pos])) break;

        int tmp = heap[pos];
        heap[pos] = heap[best];
        heap[best] = tmp;
        pos = best;
    }
}

static void sift_global(int *heap, int size, int pos) {
    while (1) {
        int left = 2 * pos + 1;
        if (left >= size) break;

        int best = left;
        int right = left + 1;
        if (right < size && global_less(heap[right], heap[left])) best = right;

        if (!global_less(heap[best], heap[pos])) break;

        int tmp = heap[pos];
        heap[pos] = heap[best];
        heap[best] = tmp;
        pos = best;
    }
}

static int pop_type(int *heap, int start, int *end) {
    int result = heap[start];
    --(*end);
    if (*end > start) {
        heap[start] = heap[*end];
        sift_type(heap, start, *end, start);
    }
    return result;
}

static int pop_global(int *heap, int *size) {
    int result = heap[0];
    --(*size);
    if (*size > 0) {
        heap[0] = heap[*size];
        sift_global(heap, *size, 0);
    }
    return result;
}

